"""Git hooks: pre-commit runs `proj check`. Hooks live in .proj/githooks/."""

from __future__ import annotations

import subprocess

from proj.config import ProjConfig

PRE_COMMIT = """\
#!/bin/sh
# Generated by `proj hooks install` — runs governance checks on every commit.
set -e
command -v proj >/dev/null 2>&1 && exec proj check || \\
    echo "proj: not installed, skipping governance check"
"""


def install(cfg: ProjConfig) -> str:
    hooks_dir = cfg.proj_dir / "githooks"
    hooks_dir.mkdir(parents=True, exist_ok=True)
    hook = hooks_dir / "pre-commit"
    if not hook.exists():
        hook.write_text(PRE_COMMIT, encoding="utf-8")
        hook.chmod(0o755)
    subprocess.run(
        ["git", "config", "core.hooksPath", str(hooks_dir.relative_to(cfg.root))],
        cwd=cfg.root, check=True,
    )
    return str(hook)
